namespace GameCoach {
static class Diagnostics {
    static readonly object Gate=new object();
    public static void Log(string message){try{lock(Gate){string path=Path.Combine(Store.Root,"voice-diagnostics.log");if(File.Exists(path)&&new FileInfo(path).Length>262144)File.WriteAllText(path,"");File.AppendAllText(path,DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss.fff")+" "+message+Environment.NewLine);}}catch{}}
}
static class Program {
    [STAThread] static void Main(string[] args) {
        Native.SetProcessDPIAware();
        Application.EnableVisualStyles(); Application.SetCompatibleTextRenderingDefault(false);
#if DIAGNOSTICS
        Tests.Run(); return;
#endif
        if (args.Contains("--self-test")) { Tests.Run(); return; }
        bool first; using (var mutex = new Mutex(true, "Local\\GameCoachLocalWatcher", out first)) {
            if (!first) { MessageBox.Show("Game Coach is already running."); return; }
            var coach=new Coach();
            if(args.Contains("--resume-run"))coach.Shown+=(s,e)=>coach.BeginInvoke(new Action(()=>coach.ResumeRun()));
            coach.Shown+=async(s,e)=>{coach.ReportLocalStartup("Loading local model…");try{await ManagedRuntime.Ensure(CancellationToken.None);coach.ReportLocalStartup(ManagedRuntime.Status);}catch(Exception ex){Diagnostics.Log("Local startup: "+ex.Message);coach.ReportLocalStartup(ex.Message);}};
            try{Application.Run(coach);}finally{ManagedRuntime.Shutdown();}
        }
    }
}
