static class Store {
    public static string Root = AppDomain.CurrentDomain.BaseDirectory;
    public static JavaScriptSerializer Json = new JavaScriptSerializer { MaxJsonLength = 20000000 };
    public static Settings Load() { try { return Json.Deserialize<Settings>(File.ReadAllText(Path.Combine(Root,"settings.json"))); } catch { return new Settings(); } }
    public static void Save(Settings s) { File.WriteAllText(Path.Combine(Root,"settings.json"), Json.Serialize(s)); }
    public static string Key() {
        string path = Path.Combine(Root,"api-key.dpapi");
        if (File.Exists(path)) return Encoding.UTF8.GetString(ProtectedData.Unprotect(File.ReadAllBytes(path), null, DataProtectionScope.CurrentUser));
        return Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "";
    }
    public static void Key(string key) { File.WriteAllBytes(Path.Combine(Root,"api-key.dpapi"), ProtectedData.Protect(Encoding.UTF8.GetBytes(key.Trim()), null, DataProtectionScope.CurrentUser)); }
}
