static class AnswerStream {
 static readonly HttpClient client=new HttpClient{Timeout=Timeout.InfiniteTimeSpan};
 public static bool ChoiceReport(string question){string q=question.ToLowerInvariant().Trim().Replace('\u2019','\'');return !System.Text.RegularExpressions.Regex.IsMatch(q,@"\b(what|why|how|which|should|better|compare|plan|search|web|verify|if|maybe|might|not|never|between|or|considering)\b")&&!q.Contains("?")&&System.Text.RegularExpressions.Regex.IsMatch(q,@"^i(?:(?: have|'ve)? (?:took|taken|picked(?: up)?|chose|chosen|selected|equipped|bought)|(?: am|'m) (?:choosing|taking|picking(?: up)?|selecting|equipping))\s+\S");}
 public static bool Quick(string question){if(ChoiceReport(question))return true;string q=question.ToLowerInvariant().Trim().TrimEnd('.','!');if(new[]{"yes","no","okay","ok","thanks","thank you","repeat that","what did i just take"}.Contains(q))return true;if(System.Text.RegularExpressions.Regex.IsMatch(q,@"\b(what|why|how|which|should|better|compare|build|plan|synergy|upgrade|search|web|look up|verify)\b")||q.Contains("?"))return false;return System.Text.RegularExpressions.Regex.IsMatch(q,@"^(i (took|picked|chose|equipped|bought)|remember that |note that )");}
 public static string EarlyAdvice(string json){var m=System.Text.RegularExpressions.Regex.Match(json,@"^\s*\{\s*""advice""\s*:\s*(""(?:\\.|[^""\\])*"")");return m.Success?Store.Json.Deserialize<string>(m.Groups[1].Value):null;}
 static void Sources(object value,List<SourceLink> sources){var d=value as Dictionary<string,object>;if(d!=null){if(d.ContainsKey("url")){string url=d["url"] as string;Uri uri;if(Uri.TryCreate(url,UriKind.Absolute,out uri)&&(uri.Scheme=="https"||uri.Scheme=="http")&&!sources.Any(s=>s.url==url))sources.Add(new SourceLink{url=url,title=d.ContainsKey("title")?Convert.ToString(d["title"]):uri.Host});}foreach(var child in d.Values)Sources(child,sources);}else{var list=value as System.Collections.IEnumerable;if(list!=null&&!(value is string))foreach(var child in list)Sources(child,sources);}}
 public static async Task<BuildReply> Ask(string key,string payload,CancellationToken token,Action<string> adviceReady=null,Action searching=null,Action<string> sentenceReady=null){
  ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;var req=Store.Json.Deserialize<Dictionary<string,object>>(payload);req["stream"]=true;
  using(var measured=UsageMeter.Begin("cloud","coach answer",UsageMeter.Model(payload),token))using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(token))using(var request=new HttpRequestMessage(HttpMethod.Post,"https://api.openai.com/v1/responses")){
   timeout.CancelAfter(TimeSpan.FromSeconds(90));var ct=timeout.Token;request.Headers.Authorization=new AuthenticationHeaderValue("Bearer",key);request.Content=new StringContent(Store.Json.Serialize(req),Encoding.UTF8,"application/json");Vision.Requests++;if(Vision.OnRequest!=null)Vision.OnRequest();Diagnostics.Log("Streaming answer request started");
   using(var response=await client.SendAsync(request,HttpCompletionOption.ResponseHeadersRead,ct)){if(!response.IsSuccessStatusCode)throw new Exception("OpenAI answer HTTP "+(int)response.StatusCode+". Check model/tool access and billing.");using(var stream=await response.Content.ReadAsStreamAsync())using(var registration=ct.Register(()=>stream.Dispose()))using(var reader=new StreamReader(stream)){
