     if(type=="response.web_search_call.in_progress"&&searching!=null)searching();
     if(type=="response.output_text.delta"){partial.Append(Convert.ToString(evt["delta"]));if(sentenceReady!=null)foreach(var sentence in chunks.Read(partial.ToString())){Diagnostics.Log("Advice sentence ready");sentenceReady(sentence);}if(!spoken){string advice=EarlyAdvice(partial.ToString());if(!string.IsNullOrWhiteSpace(advice)){spoken=true;Diagnostics.Log("Advice ready before memory completion");if(adviceReady!=null)adviceReady(advice);}}}
     if(type=="response.completed"||type=="response.incomplete"||type=="response.failed")measured.Observe(UsageMeter.Get(evt,"response"));
     if(type=="response.completed"){var final=evt["response"] as Dictionary<string,object>;if(final==null)throw new Exception("Missing completed response.");var reply=RunMemory.Decode(Vision.Parse(Store.Json.Serialize(final)));var sources=new List<SourceLink>();object output;if(final.TryGetValue("output",out output))Sources(output,sources);reply.sources=sources.ToArray();Diagnostics.Log("Streaming answer and memory completed; sources="+sources.Count);measured.Success();return reply;}
