        next.SpeechDetected+=(s,e)=>UI(()=>{if(engine==next)heardStatus.Text="Voice check: speech detected; recognizing words...";});
        next.SpeechRecognitionRejected+=(s,e)=>UI(()=>{if(engine==next&&e.Result!=null&&InterruptCommands.AcceptThanks(e.Result.Text,e.Result.Confidence,false)){InterruptSpeech(false);return;}if(engine==next)Diagnostics.Log("Speech rejected mode="+mode+" confidence="+(e.Result==null?"none":e.Result.Confidence.ToString("0.00")));if(engine==next)heardStatus.Text="Voice check: sound heard, but words were not recognized. Try speaking clearly after the tone.";});
        next.AudioSignalProblemOccurred+=(s,e)=>UI(()=>{if(engine==next){signalProblem=e.AudioSignalProblem.ToString();heardStatus.Text=e.AudioSignalProblem==AudioSignalProblem.NoSignal?"Microphone is open; no speech detected yet.":"Microphone signal: "+e.AudioSignalProblem+". Check your Windows microphone input.";}});
        signalProblem="";Diagnostics.Log("Opening microphone question="+questionMode);audio=new MicStream(-1);next.SetInputToAudioStream(audio,new SpeechAudioFormatInfo(16000,AudioBitsPerSample.Sixteen,AudioChannel.Mono));next.RecognizeAsync(RecognizeMode.Multiple);
    }
    bool IsWake(string text){return text==Normalize(settings.Wake)||text=="hey coach"||text=="coach";}
    void Cue(bool ready){int volume=voiceVolume.Value;Task.Run(()=>{try{const int rate=24000;int count=7200;using(var ms=new MemoryStream()){using(var w=new BinaryWriter(ms,Encoding.UTF8,true)){w.Write(Encoding.ASCII.GetBytes("RIFF"));w.Write(36+count*2);w.Write(Encoding.ASCII.GetBytes("WAVEfmt "));w.Write(16);w.Write((short)1);w.Write((short)1);w.Write(rate);w.Write(rate*2);w.Write((short)2);w.Write((short)16);w.Write(Encoding.ASCII.GetBytes("data"));w.Write(count*2);for(int i=0;i<count;i++){double frequency=(i<count/2)==ready?660:880;double envelope=Math.Min(1,Math.Min(i%3600,3599-i%3600)/180.0);w.Write((short)(Math.Sin(2*Math.PI*frequency*i/rate)*6000*volume/100*envelope));}}ms.Position=0;using(var player=new System.Media.SoundPlayer(ms))player.PlaySync();}}catch(Exception ex){Diagnostics.Log("Cue failed: "+ex.GetType().Name);}});}
    static string Normalize(string text){return string.Join(" ",new string(text.ToLowerInvariant().Select(c=>char.IsLetterOrDigit(c)?c:' ').ToArray()).Split(new[]{' ','\t','\r','\n'},StringSplitOptions.RemoveEmptyEntries));}
    async void ActivateQuestion(){if(busy||mode=="Recording"||mode=="Transcribing")return;CancelMoment();CancellationTokenSource recording=null;try{SaveSettings();string apiKey=GetKey();listening=true;listen.Text="Pause coaching";listen.BackColor=Color.FromArgb(145,55,55);SetSettingsEnabled(false);CloseRecognizer();busy=true;mode="Recording";recording=new CancellationTokenSource();recording.CancelAfter(TimeSpan.FromSeconds(50));cancel=recording;SetStatus("Speak after the rising tone. Pause when finished; maximum 15 seconds.");heardStatus.Text="Connecting microphone; wait for the ready tone.";SetStatus("Opening microphone. The ready tone plays only after audio arrives.");byte[] wav=await Transcription.Record(v=>Interlocked.Exchange(ref nativeLevel,v),recording.Token,()=>UI(()=>{micUnavailable=false;Cue(true);heardStatus.Text="Recording your question for OpenAI transcription.";SetStatus("Microphone ready. Ask your question now.");}));mode="Transcribing";BeginReplySpeech(VoiceCueCache.Thinking);SetStatus("Thinking for a sec · transcribing your question. Say thanks to silence speech.");string text=await Transcription.Ask(apiKey,wav,recording.Token);wav=null;recording.Token.ThrowIfCancellationRequested();question.Text=text;heardStatus.Text="Heard: "+text;busy=false;cancel=null;if(InterruptCommands.Thanks(text)){InterruptSpeech(false);await FinishReplySpeech();return;}if(IsWake(Normalize(text)))throw new Exception("Only the wake phrase was heard. Say hey coach, wait for the tone, then ask your question.");await Submit(text);await FinishReplySpeech();}catch(OperationCanceledException){if(!closing){busy=false;if(listening)RestartWake();SetStatus("Voice request cancelled or timed out.");}}catch(Exception ex){Diagnostics.Log("Voice input failed: "+ex.Message);if(ex is IOException)micUnavailable=true;busy=false;if(!closing){if(listening)RestartWake();SetStatus(ex.Message);answer.Text=ex.Message;Cue(false);}}finally{CancelReplySpeech();if(recording!=null){if(cancel==recording)cancel=null;recording.Dispose();}if(!closing&&listening&&!busy&&engine==null)RestartWake();}}

    string ReadRun(){try{SaveMemorySync.Refresh(true);return File.Exists(RunPath)?File.ReadAllText(RunPath):"No run notes yet.";}catch{return "Run notes unavailable.";}}
    void StartRun(){BeginSetup();}
    void ClearRun(){BeginSetup();}
    async Task StartBoss(){if(busy)return;SaveMemorySync.Refresh();await Submit(BossBriefing.Question(RunMemory.Load().gameState));}
    void StopBoss(string message){bossMode=false;InterruptSpeech(false);SetStatus("Boss tips stay in the opening-dialogue overlay. Ask coach for an explanation when needed.");if(listening&&!busy)RestartWake();}
    protected override void WndProc(ref Message m){if(m.Msg==0x312&&m.WParam.ToInt32()==1){if(replySpeech!=null||busy)InterruptSpeech(true);else ActivateQuestion();}base.WndProc(ref m);}
    async Task Submit(string text,bool itemCheck=false){if(busy||string.IsNullOrWhiteSpace(text))return;CancelMoment();if(bossMode)StopBoss("Boss coaching paused for a one-shot question.");        string normalized=Normalize(text);if(new[]{"use build ","switch build to ","choose build "}.Any(p=>normalized.StartsWith(p))){SaveMemorySync.Refresh(true);string result=BuildPlanner.SelectCommand(text,RunMemory.Load().gameState);RefreshMemory();answer.Text=result;busy=true;try{await Speak(result);}finally{busy=false;if(listening&&!closing)RestartWake();}return;}string experiment=RunLab.Command(text);if(experiment.Length>0){await RunExperiment(experiment,true);return;}if(normalized.StartsWith("remember for next run ")){string lesson=text.Substring(text.ToLowerInvariant().IndexOf("remember for next run")+21).Trim();await RememberLesson(lesson);return;}if(normalized.Contains("add to setup")||normalized.Contains("more setup")){BeginSetup(false);return;}if(normalized.Contains("setup complete")||normalized.Contains("finish setup")){FinishSetup();return;}if(normalized.Contains("start my run")||normalized.Contains("starting the run")||normalized.Contains("starting a run")||normalized.Contains("starting my run")||normalized.Contains("here s my setup")||normalized.Contains("here is my setup")){BeginSetup();if(setupReview){RunMemory.Append(text,new BuildReply{advice="Setup started.",updates=new BuildUpdate[0]});RefreshMemory();}return;}if(setupReview){RunMemory.Append(text,new BuildReply{advice="Setup narration saved.",updates=new BuildUpdate[0]});RefreshMemory();SetStatus("Setup narration saved; continue showing equipment, then say coach setup complete.");return;}if(normalized.Contains("check items")){itemCheck=true;text=text+"\nRead the current "+settings.Game+" item/boon screen. Count only clearly visible items. Identify any item visibly selected or already acquired. Separate selected/owned items from the other choices. Report uncertainty if the screenshot does not show what was chosen.";}if(normalized=="boss fight"){await StartBoss();return;}if(normalized.Contains("stop boss fight")){StopBoss("Boss coaching stopped.");return;}

bool choiceReport=AnswerStream.ChoiceReport(text);string failure=null;bool replyReceived=false;int spokenChunks=0;
try{try{
 Diagnostics.Log("Question submitted");SaveSettings();string apiKey=GetKey();busy=true;mode="Thinking";cancel=new CancellationTokenSource();listen.Text="Pause coaching";SetSettingsEnabled(false);
 bool alreadyAcknowledged=replySpeech!=null;BeginReplySpeech(alreadyAcknowledged?null:choiceReport?VoiceCueCache.GotIt:VoiceCueCache.Thinking);var speech=replySpeech;
 SetStatus("Thinking for a sec · reading your screen and run memory. Say thanks to silence speech.");
 // Clear the screen for capture and leave the game in charge of focus.
 // Restoring after a reply also activates a window that was behind the game.
 if(WindowState!=FormWindowState.Minimized){WindowState=FormWindowState.Minimized;await Task.Delay(200,cancel.Token);}
 var screen=Screen.AllScreens.FirstOrDefault(s=>s.DeviceName==settings.Display);if(screen==null)throw new Exception("Selected display was disconnected. Select another display.");
 RunMemory.Append(text,new BuildReply{advice="",updates=OfferMemory.PlayerReport(text)});if(choiceReport){answer.Text="Got it. Recording your choice.";replyReceived=true;if(alreadyAcknowledged)speech.Enqueue(VoiceCueCache.GotIt);}
 var image=Vision.Capture(screen.Bounds);string context=ReadRun();string payload=RunMemory.Payload(settings.Model,settings.Game,text,new[]{image},context);image=null;
 var buildReply=await AnswerStream.Ask(apiKey,payload,cancel.Token,advice=>{answer.Text=advice;replyReceived=true;},()=>SetStatus("Checking web sources for this question..."),sentence=>{if(!choiceReport){spokenChunks++;speech.Enqueue(sentence);mode="Speaking";}});
 cancel.Token.ThrowIfCancellationRequested();RunMemory.Append("",buildReply);RefreshMemory();var reply=buildReply.advice;answer.Text=reply+SourceText(buildReply.sources);replyReceived=true;Diagnostics.Log("Answer received");history.Add("Player: "+text+"\nCoach: "+reply);while(history.Count>5)history.RemoveAt(0);
 if(!choiceReport&&spokenChunks==0)speech.Enqueue(reply);SetStatus(speech.Silenced?"Reply silenced; memory saved.":"Speaking answer. Say thanks to silence this reply.");await FinishReplySpeech();Diagnostics.Log("Voice playback completed");cancel.Token.ThrowIfCancellationRequested();
}catch(OperationCanceledException){failure=interruptQuestion?null:"Request cancelled or timed out.";}catch(Exception ex){failure=(replyReceived?"Advice received, but response completion or voice failed: ":"Answer failed: ")+ex.Message;}}
finally{CancelReplySpeech();busy=false;if(!closing){SetSettingsEnabled(!listening);listen.Text=listening?"Pause coaching":"Start coaching";if(listening&&!interruptQuestion)RestartWake();else mode=listening?"Wake":"Stopped";if(failure!=null){Diagnostics.Log(failure);SetStatus(failure+" Listening remains active while coaching is active.");if(!replyReceived)answer.Text=failure;else answer.AppendText(Environment.NewLine+Environment.NewLine+failure);Cue(false);}}if(cancel!=null){cancel.Dispose();cancel=null;}}
}

    void ScheduleReconnect(){if(!listening||closing)return;micUnavailable=true;mode="Reconnecting";int seconds=++recoveryAttempts<=3?2:30;reconnectAt=DateTime.UtcNow.AddSeconds(seconds);Diagnostics.Log("Microphone recovery scheduled in "+seconds+" seconds; run retained");SetStatus("Microphone unavailable. Run remains active and saved; retrying in "+seconds+" seconds. Typed questions still work.");}
    void EnsureInterruptListener(){if(!listening||engine!=null||closing)return;try{OpenRecognizer(false,true);}catch(Exception ex){Diagnostics.Log("Interrupt listener unavailable: "+ex.GetType().Name);ScheduleReconnect();}}
    void BeginReplySpeech(string cue){if(replySpeech==null)replySpeech=new ReplyAudio(GetKey(),voices.SelectedItem==null?"cedar":voices.SelectedItem.ToString(),voiceVolume.Value,voiceRate.Value);if(!string.IsNullOrWhiteSpace(cue))replySpeech.Enqueue(cue);EnsureInterruptListener();}
    async Task FinishReplySpeech(){var current=replySpeech;if(current==null)return;try{await current.Finish();}finally{current.Dispose();if(replySpeech==current){replySpeech=null;CloseRecognizer();}}}
    void CancelReplySpeech(){var current=replySpeech;replySpeech=null;if(current!=null)current.Dispose();}
    async void PrepareCues(){if(cuePreparation!=null||voiceVolume.Value==0)return;var operation=new CancellationTokenSource();cuePreparation=operation;try{await VoiceCueCache.Prepare(GetKey(),voices.SelectedItem==null?"cedar":voices.SelectedItem.ToString(),voiceRate.Value,operation.Token);}catch(Exception ex){Diagnostics.Log("Voice cue preparation deferred: "+ex.GetType().Name);}finally{if(cuePreparation==operation)cuePreparation=null;operation.Dispose();}}
    void InterruptSpeech(bool ask){CancelMoment();if(localPanel!=null)localPanel.SilenceVoice();Diagnostics.Log(ask?"Speech interrupted for new question":"Thanks accepted: current reply silenced");if(replySpeech!=null)replySpeech.Silence();if(ask){interruptQuestion=true;bossMode=false;if(cancel!=null)cancel.Cancel();}else{SetStatus("Reply silenced. Run and watcher remain active.");heardStatus.Text="Heard thanks · speech stopped.";}}
    async Task Speak(string text){BeginReplySpeech(null);replySpeech.Enqueue(text);mode="Speaking";try{await FinishReplySpeech();}finally{if(!closing)mode=busy?"Thinking":"Wake";}}


}
static class Tests {
    public static void Run(){int initialRequests=Vision.Requests;var lines=new List<string>();Action<string,Action> test=(name,act)=>{try{act();lines.Add("PASS "+name);}catch(Exception ex){lines.Add("FAIL "+name+": "+ex.Message);}};
        test("Idle has no screenshot/network activity",()=>{int captures=Vision.Captures,requests=Vision.Requests;Thread.Sleep(250);if(Vision.Captures!=captures||Vision.Requests!=requests)throw new Exception("unexpected activity during idle interval");});
        test("Windows user encryption round trip",()=>{var b=Encoding.UTF8.GetBytes("test-only");if(Encoding.UTF8.GetString(ProtectedData.Unprotect(ProtectedData.Protect(b,null,DataProtectionScope.CurrentUser),null,DataProtectionScope.CurrentUser))!="test-only")throw new Exception("mismatch");});
        test("Microphone PCM capture, 2 seconds locally",()=>{using(var mic=new MicStream(-1)){Thread.Sleep(2000);lines.Add("INFO mic bytes="+mic.BytesReceived+", peak="+mic.Peak+", devices="+MicStream.Devices().Count);if(mic.BytesReceived<16000)throw new Exception("no PCM samples");}});
        test("Offline wake recognition from synthesized audio",()=>{using(var ms=new MemoryStream()) {using(var v=new SpeechSynthesizer()){v.SetOutputToWaveStream(ms);v.Speak("hey coach");}ms.Position=0;using(var r=new SpeechRecognitionEngine(new System.Globalization.CultureInfo("en-US"))){var gb=new GrammarBuilder(new Choices("hey coach")){Culture=new System.Globalization.CultureInfo("en-US")};r.LoadGrammar(new Grammar(gb));r.SetInputToWaveStream(ms);var result=r.Recognize();if(result==null||result.Text!="hey coach")throw new Exception("wake not recognized");lines.Add("INFO synthetic wake confidence="+result.Confidence);}}});
        test("Offline dictation from synthesized audio",()=>{using(var ms=new MemoryStream()){using(var v=new SpeechSynthesizer()){v.SetOutputToWaveStream(ms);v.Speak("What should I choose next");}ms.Position=0;using(var r=new SpeechRecognitionEngine(new System.Globalization.CultureInfo("en-US"))){r.LoadGrammar(new DictationGrammar());r.SetInputToWaveStream(ms);var result=r.Recognize();if(result==null)throw new Exception("dictation not recognized");lines.Add("INFO synthetic question="+result.Text);}}});
        test("Explicit local screenshot test, discarded in memory",()=>{var bytes=Vision.Capture(Screen.PrimaryScreen.Bounds);using(var ms=new MemoryStream(bytes))using(var img=Image.FromStream(ms)){lines.Add("INFO capture="+img.Width+"x"+img.Height+", jpeg bytes="+bytes.Length);if(bytes.Length<5000)throw new Exception("suspiciously empty capture");}});
        test("Responses payload and parsing",()=>{var body=Vision.Payload("gpt-4.1-mini","","test",new byte[]{1,2,3},"");var data=Store.Json.Deserialize<Dictionary<string,object>>(body);if((bool)data["store"]||!body.Contains("input_image"))throw new Exception("invalid payload");var answer=Vision.Parse("{\"output\":[{\"type\":\"message\",\"content\":[{\"type\":\"output_text\",\"text\":\"Test reply\"}]}]}");if(answer!="Test reply")throw new Exception("invalid reply");});
        test("No network during self-test",()=>{if(Vision.Requests!=initialRequests)throw new Exception("network request made");});
        test("Spoken output to Windows default device",()=>{using(var v=new SpeechSynthesizer()){v.SetOutputToDefaultAudioDevice();v.Speak("Game Coach setup test complete.");}});
        File.WriteAllLines(Path.Combine(Store.Root,"verification.txt"),lines);
    }
}
